mapper.select:
/* LeaveApprovalNotiMapper.selectNodeAdmins */
SELECT A.USER_CD
  FROM TB_USER A
 WHERE A.CMPNY_CD = #{cmpnyCd}
   AND A.USE_YN   = 'Y'
   AND A.ACCOUNT_STATUS = '01'
   AND A.USER_CD IN (
         SELECT N.MAIN_ADMIN_CD
           FROM TB_SITE_NODE N
                INNER JOIN TB_USER W
                   ON  W.CMPNY_CD = N.CMPNY_CD
                   AND W.NODE_CD  = N.NODE_CD
                   AND W.SITE_CD  = N.SITE_CD
          WHERE N.CMPNY_CD = #{cmpnyCd}
            AND N.SITE_CD  = #{siteCd}
            AND W.USER_CD  = #{userCd}
            AND NULLIF(TRIM(N.MAIN_ADMIN_CD), '') IS NOT NULL
         UNION
         SELECT N.SUB_ADMIN_CD
           FROM TB_SITE_NODE N
                INNER JOIN TB_USER W
                   ON  W.CMPNY_CD = N.CMPNY_CD
                   AND W.NODE_CD  = N.NODE_CD
                   AND W.SITE_CD  = N.SITE_CD
          WHERE N.CMPNY_CD = #{cmpnyCd}
            AND N.SITE_CD  = #{siteCd}
            AND W.USER_CD  = #{userCd}
            AND NULLIF(TRIM(N.SUB_ADMIN_CD), '') IS NOT NULL
       )

/* LeaveApprovalNotiMapper.selectUserNm */
SELECT U.USER_NM
  FROM TB_USER U
 WHERE U.CMPNY_CD       = #{cmpnyCd}
   AND U.USER_CD        = #{userCd}
   AND U.USE_YN         = 'Y'
   AND U.ACCOUNT_STATUS = '01'
 LIMIT 1

/* LeaveApprovalNotiMapper.countOutboxByDedupKey */
SELECT COUNT(*)
  FROM TB_NOTI_OUTBOX O
 WHERE O.CMPNY_CD  = #{cmpnyCd}
   AND O.DEDUP_KEY = #{dedupKey}
